python3 - <<'PY'
from pathlib import Path
for name in ['invoice', 'report']:
    p = Path(f'src/{name}.ts')
    s = p.read_text().replace(f"import {{ {name}Amount }} from './{name}Amount';", "import { formatAmount } from './money';").replace(f'{name}Amount(', 'formatAmount(')
    p.write_text(s)
    Path(f'src/{name}Amount.ts').unlink()
PY
cat > checks/public.cjs <<'EOF'
const assert = require('node:assert/strict');
const { formatAmount } = require('../.build/money');
const { renderInvoice } = require('../.build/invoice');
const { renderReport } = require('../.build/report');

const cases = [
  [123, '1.23'],
  [0, '0.00'],
  [-1, '-0.01'],
  [1, '0.01'],
  [99, '0.99'],
  [100, '1.00'],
  [-100, '-1.00'],
  [-123, '-1.23'],
  [1205, '12.05'],
  [-1205, '-12.05'],
];
for (const [cents, amount] of cases) {
  assert.equal(formatAmount(cents), amount);
  assert.equal(renderInvoice('inv', cents), 'inv: $' + amount);
}
assert.equal(renderReport([{ id: 'a', cents: 0 }, { id: 'b', cents: -1 }]), 'a,0.00\nb,-0.01');
assert.equal(
  renderReport(cases.map(([cents], index) => ({ id: String(index), cents }))),
  cases.map(([, amount], index) => index + ',' + amount).join('\n'),
);
assert.equal(renderReport([]), '');
EOF
tsc -p tsconfig.json && node checks/public.cjs
 grep -R -nE 'invoiceAmount|reportAmount' src || true

